/*
# Create products table

1. New Tables
- `products`
  - `id` (bigint, primary key, auto-increment)
  - `name` (text, not null) — product name in Arabic
  - `description` (text, not null) — full product description in Arabic
  - `short_description` (text) — short description for cards
  - `price` (numeric, not null) — price in QAR
  - `old_price` (numeric) — original price if on sale
  - `category` (text, not null) — category id (boxes, flowers, chocolate, etc.)
  - `image_url` (text, not null) — main product image URL
  - `gallery` (jsonb) — array of additional image URLs
  - `available` (boolean, default true) — whether the product is in stock
  - `visible` (boolean, default true) — whether to show on the storefront
  - `badge` (text) — optional badge: 'new', 'bestseller', 'sale'
  - `rating` (numeric, default 5.0) — product rating (0-5)
  - `reviews_count` (integer, default 0) — number of reviews
  - `features` (jsonb) — array of feature strings
  - `occasions` (jsonb) — array of occasion ids
  - `created_at` (timestamptz, default now())
  - `updated_at` (timestamptz, default now())

2. Security
- Enable RLS on `products`.
- Allow anon + authenticated to read visible products (public storefront).
- No write policies (admin-only via dashboard).

3. Notes
- This is a single-tenant storefront with no auth — all visitors browse the same catalog.
- Only rows with `visible = true` are exposed to the frontend.
*/

CREATE TABLE IF NOT EXISTS products (
  id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  name text NOT NULL,
  description text NOT NULL,
  short_description text,
  price numeric(10, 2) NOT NULL,
  old_price numeric(10, 2),
  category text NOT NULL,
  image_url text NOT NULL,
  gallery jsonb DEFAULT '[]'::jsonb,
  available boolean NOT NULL DEFAULT true,
  visible boolean NOT NULL DEFAULT true,
  badge text,
  rating numeric(2, 1) NOT NULL DEFAULT 5.0,
  reviews_count integer NOT NULL DEFAULT 0,
  features jsonb DEFAULT '[]'::jsonb,
  occasions jsonb DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "anon_select_visible_products" ON products;
CREATE POLICY "anon_select_visible_products"
ON products FOR SELECT
TO anon, authenticated
USING (visible = true);

-- Seed initial product data
INSERT INTO products (name, description, short_description, price, old_price, category, image_url, gallery, available, visible, badge, rating, reviews_count, features, occasions) VALUES
('بوكس الورد الملكي', 'بوكس الورد الملكي عبارة عن مجموعة فاخرة تجمع بين الورد الأحمر الطبيعي الطازج وشوكولاتة فاخرة، مع إمكانية إضافة بطاقة إهداء مخصصة. مصمم بعناية ليكون الهدية المثالية للتعبير عن أسمى مشاعر الحب والتقدير في المناسبات الخاصة.', 'بوكس ورد أحمر فاخر مع شوكولاتة وبطاقة إهداء', 185, NULL, 'boxes', 'https://images.pexels.com/photos/30632274/pexels-photo-30632274.png?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/30632274/pexels-photo-30632274.png?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/5714433/pexels-photo-5714433.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/5404619/pexels-photo-5404619.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/13977744/pexels-photo-13977744.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, 'bestseller', 4.9, 128, '["ورد طبيعي طازج","شوكولاتة فاخرة","بطاقة إهداء مجانية","تغليف فاخر"]', '["anniversary","wedding","surprise"]'),
