('بوكس عيد ميلاد مميز', 'بوكس عيد ميلاد مميز يحتوي على ورد طبيعي وشوكولاتة وحلويات احتفالية مع بطاقة تهنئة مخصصة. مصمم بألوان مبهجة ليضيف لمسة فرح وسرور على عيد ميلاد من تحب.', 'بوكس احتفالي متكامل لعيد ميلاد لا يُنسى', 220, NULL, 'birthday', 'https://images.pexels.com/photos/5404193/pexels-photo-5404193.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/5404193/pexels-photo-5404193.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/28159640/pexels-photo-28159640.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/36663545/pexels-photo-36663545.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/20699855/pexels-photo-20699855.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, 'bestseller', 4.7, 72, '["ورد طبيعي","شوكولاتة وحلويات","بطاقة تهنئة","تغليف احتفالي"]', '["birthday","surprise"]'),
('دبدوب مع ورد', 'دبدوب ناعم عالي الجودة مع باقة ورد وردي طبيعي، هدية مثالية للتعبير عن المشاعر الرقيقة. يجمع بين الدفء والجمال ليكون هدية لا تُنسى لمن تحب.', 'دبدوب ناعم مع باقة ورد وردي رائعة', 175, NULL, 'dolls', 'https://images.pexels.com/photos/35579570/pexels-photo-35579570.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/35579570/pexels-photo-35579570.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/35579568/pexels-photo-35579568.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/12109904/pexels-photo-12109904.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/1214202/pexels-photo-1214202.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, NULL, 4.6, 54, '["دبدوب فرو ناعم","ورد وردي طبيعي","تغليف أنيق","مقاس مثالي"]', '["birthday","apology","surprise"]'),
('بوكس تخرج', 'بوكس تخرج مصمم خصيصًا للاحتفال بإنجاز التخرج، يحتوي على ورد وحلويات وبطاقة تهنئة قابلة للتخصيص. الهدية المثالية لتهنئة الخريجين بهذا الإنجاز الكبير.', 'بوكس احتفالي مميز للاحتفال بالتخرج', 195, NULL, 'graduation', 'https://images.pexels.com/photos/25643174/pexels-photo-25643174.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/25643174/pexels-photo-25643174.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/12414845/pexels-photo-12414845.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/25643178/pexels-photo-25643178.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/30147740/pexels-photo-30147740.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, 'new', 4.8, 43, '["تصميم احتفالي","ورد طبيعي","حلويات","بطاقة تهنئة"]', '["graduation"]'),
