('بوكس عناية شخصية', 'بوكس عناية شخصية يحتوي على تشكيلة مختارة من منتجات العناية الفاخرة بالبشرة، هدية مثالية لمن يستحق الرعاية والاهتمام. منتجات طبيعية بجودة عالية.', 'تشكيلة منتجات عناية فاخرة للعناية بالبشرة', 230, NULL, 'boxes', 'https://images.pexels.com/photos/6634844/pexels-photo-6634844.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/6634844/pexels-photo-6634844.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/4841534/pexels-photo-4841534.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/17307534/pexels-photo-17307534.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/4841273/pexels-photo-4841273.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, NULL, 4.7, 52, '["منتجات طبيعية","جودة عالية","تشكيلة مختارة","بوكس أنيق"]', '["birthday","thanks","surprise"]'),
('بوكيه ورد وردي', 'بوكيه ورد وردي رومانطقية مصمم بعناية، يرمز للحب والرقة. خيار مثالي للتعبير عن المشاعر النبيلة بأسلوب راقٍ وأنيق.', 'باقة ورد وردي رومانطقية بتصميم ساحر', 155, NULL, 'flowers', 'https://images.pexels.com/photos/12622593/pexels-photo-12622593.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/12622593/pexels-photo-12622593.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/532456/pexels-photo-532456.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/13282385/pexels-photo-13282385.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/28882158/pexels-photo-28882158.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, 'new', 4.8, 64, '["ورد وردي طبيعي","تصميم رومانطقي","تغليف أنيق","طازج مضمون"]', '["birthday","anniversary","apology","surprise"]'),
('بوكس ذكرى خاصة', 'بوكس ذكرى خاصة مصمم للاحتفال بالمناسبات والذكريات المميزة، يحتوي على ورد فاخر وشوكولاتة وهدية تذكارية. اجعل ذكرياتك لا تُنسى بهذا البوكس الراقي.', 'بوكس فاخر للاحتفال بالمناسبات والذكريات', 275, NULL, 'boxes', 'https://images.pexels.com/photos/6699449/pexels-photo-6699449.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '["https://images.pexels.com/photos/6699449/pexels-photo-6699449.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/13983704/pexels-photo-13983704.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/13977744/pexels-photo-13977744.jpeg?auto=compress&cs=tinysrgb&h=650&w=940","https://images.pexels.com/photos/5404619/pexels-photo-5404619.jpeg?auto=compress&cs=tinysrgb&h=650&w=940"]', true, true, 'bestseller', 4.9, 45, '["ورد فاخر","شوكولاتة","هدية تذكارية","تغليف فاخر"]', '["anniversary","wedding","surprise"]')
